import { useRef, useEffect } from 'react';

// Map color name → CSS var string
const COLOR_VARS = {
  blue:   'var(--accent)',
  green:  'var(--green)',
  orange: 'var(--orange)',
  red:    'var(--red)',
};

export default function StatsCard({ label, sublabel, value, color, icon }) {
  const accentVar = COLOR_VARS[color] || COLOR_VARS.blue;
  const prevRef   = useRef(value);

  // Trigger re-animation key on value change
  const keyRef = useRef(0);
  if (prevRef.current !== value) {
    keyRef.current += 1;
    prevRef.current = value;
  }

  return (
    <div className="card" style={{ padding: 0, cursor: 'default' }}>
      {/* Top accent bar */}
      <div className="stat-top-bar" style={{ background: accentVar }} />

      <div style={{ padding: '18px 18px 16px' }}>
        {/* Label row */}
        <div style={{
          display: 'flex',
          alignItems: 'flex-start',
          justifyContent: 'space-between',
          marginBottom: 12,
        }}>
          <div>
            <div style={{
              fontFamily: 'var(--font-display)',
              fontSize: 8.5,
              fontWeight: 600,
              letterSpacing: '2px',
              textTransform: 'uppercase',
              color: 'var(--text-3)',
              marginBottom: 3,
            }}>
              {label}
            </div>
            <div style={{
              fontFamily: 'var(--font-mono)',
              fontSize: 8,
              color: 'var(--text-4)',
              letterSpacing: '1px',
            }}>
              {sublabel}
            </div>
          </div>

          <div style={{
            fontSize: 28,
            opacity: 0.15,
            userSelect: 'none',
            lineHeight: 1,
          }}>
            {icon}
          </div>
        </div>

        {/* Value */}
        <div
          key={keyRef.current}
          className="stat-value"
          style={{ color: accentVar, textShadow: `0 0 24px ${accentVar}60` }}
        >
          {String(value).padStart(2, '0')}
        </div>

        {/* Mini sparkline bar (decorative) */}
        <div style={{
          marginTop: 10,
          height: 3,
          borderRadius: 2,
          background: 'rgba(255,255,255,0.05)',
          overflow: 'hidden',
        }}>
          <div style={{
            height: '100%',
            width: `${Math.min(100, (value / 100) * 100 + 20)}%`,
            background: `linear-gradient(90deg, ${accentVar}44, ${accentVar})`,
            borderRadius: 2,
            transition: 'width 0.8s ease',
          }} />
        </div>
      </div>
    </div>
  );
}
